// Compute time range for freeBusy query
const queryInput = $input.all()[0].json.query || '';
const dateMatch = queryInput.match(/(\d{4}-\d{2}-\d{2})/);
const preferred_date = dateMatch ? dateMatch[1] : null;

const BIZ_START = 9;
const BIZ_END = 17;
const DAYS_AHEAD = 7;
const OFFSET_MS = 8 * 60 * 60 * 1000; // WITA = UTC+8

const now = new Date();
const nowWITA = new Date(now.getTime() + OFFSET_MS);

let searchStart = new Date(Date.UTC(
  nowWITA.getUTCFullYear(), nowWITA.getUTCMonth(), nowWITA.getUTCDate(),
  BIZ_START, 0, 0
) - OFFSET_MS);

if (now > searchStart) {
  const nextHour = new Date(now);
  nextHour.setMinutes(0, 0, 0);
  nextHour.setHours(nextHour.getHours() + 1);
  searchStart = nextHour;
}

if (preferred_date) {
  const pref = new Date(preferred_date + 'T' + String(BIZ_START).padStart(2,'0') + ':00:00+08:00');
  if (pref > searchStart) searchStart = pref;
}

const searchEnd = new Date(searchStart.getTime() + DAYS_AHEAD * 24 * 60 * 60 * 1000);

return [{
  json: {
    timeMin: searchStart.toISOString(),
    timeMax: searchEnd.toISOString(),
    searchStartMs: searchStart.getTime(),
    searchEndMs: searchEnd.getTime(),
    query: queryInput
  }
}];

// Process FreeBusy response and generate available slots
const freeBusyResp = $input.all()[0].json;
const prevData = $('Prepare Dates').all()[0].json;
const searchStartMs = prevData.searchStartMs;
const searchEndMs = prevData.searchEndMs;

const BIZ_START = 9;
const BIZ_END = 17;
const SLOT_MINUTES = 60;
const OFFSET_MS = 8 * 60 * 60 * 1000;

// Extract busy periods
const cals = freeBusyResp.calendars || {};
const primaryKey = Object.keys(cals)[0] || 'primary';
const busySlots = cals[primaryKey]?.busy || [];

// Generate available slots
const slots = [];
const cursor = new Date(searchStartMs);
const searchEnd = new Date(searchEndMs);

// Round up to next hour
if (cursor.getMinutes() > 0) {
  cursor.setMinutes(0, 0, 0);
  cursor.setTime(cursor.getTime() + 60 * 60 * 1000);
}

while (cursor < searchEnd && slots.length < 15) {
  const witaTime = new Date(cursor.getTime() + OFFSET_MS);
  const day = witaTime.getUTCDay();
  const hour = witaTime.getUTCHours();

  // Skip weekends
  if (day === 0 || day === 6) {
    const daysToMon = day === 0 ? 1 : 2;
    cursor.setTime(cursor.getTime() + daysToMon * 24 * 60 * 60 * 1000);
    const c2 = new Date(cursor.getTime() + OFFSET_MS);
    cursor.setTime(Date.UTC(c2.getUTCFullYear(), c2.getUTCMonth(), c2.getUTCDate(), BIZ_START, 0, 0) - OFFSET_MS);
    continue;
  }

  // Skip outside business hours
  if (hour < BIZ_START || hour >= BIZ_END) {
    const c2 = new Date(cursor.getTime() + OFFSET_MS);
    const nextDay = new Date(Date.UTC(c2.getUTCFullYear(), c2.getUTCMonth(), c2.getUTCDate() + 1, BIZ_START, 0, 0) - OFFSET_MS);
    cursor.setTime(nextDay.getTime());
    continue;
  }

  const slotStart = new Date(cursor);
  const slotEnd = new Date(cursor.getTime() + SLOT_MINUTES * 60 * 1000);

  // Check if busy
  const isBusy = busySlots.some(b => {
    const busyStart = new Date(b.start);
    const busyEnd = new Date(b.end);
    return slotStart < busyEnd && slotEnd > busyStart;
  });

  if (!isBusy) {
    const witaStart = new Date(slotStart.getTime() + OFFSET_MS);
    const dayNames = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'];
    const dayName = dayNames[witaStart.getUTCDay()];
    const dateStr = witaStart.toISOString().slice(0,10);
    const timeStr = String(witaStart.getUTCHours()).padStart(2,'0') + ':' + String(witaStart.getUTCMinutes()).padStart(2,'0');
    slots.push({
      n: slots.length + 1,
      day: dayName,
      date: dateStr,
      time: timeStr + ' WITA',
      iso: slotStart.toISOString()
    });
  }

  cursor.setTime(cursor.getTime() + SLOT_MINUTES * 60 * 1000);
}

if (slots.length === 0) {
  return [{ json: { response: 'No available slots found in the next 7 business days. Please suggest a different date range.' } }];
}

let msg = 'Available consultation slots at ILOT Legal Office, Bali:\n\n';
for (const s of slots) {
  msg += `${s.n}. ${s.day} ${s.date} at ${s.time}\n`;
}
msg += '\nPlease tell the customer to pick a slot number or suggest another date.';

return [{ json: { response: msg } }];
